// $json.text = respuesta del modelo AI
// $('Preparar por Blog').item.json = datos del blog
const rawText = $json.text || $json.output || $json.response || '';
const prev = $('Preparar por Blog').item.json;

console.log('=== PARSEAR TÍTULOS ===');
console.log('Blog: ' + prev.blogId + ' nicho=' + prev.nicho);
console.log('rawText length: ' + rawText.length);
console.log('rawText: ' + rawText.substring(0, 500));

if (!rawText || rawText.trim().length === 0) {
  throw new Error('Modelo AI devolvio respuesta vacia');
}

let titlesData;
const tries = [
  () => JSON.parse(rawText.trim()),
  () => JSON.parse(rawText.replace(/^```json\s*/i,'').replace(/^```\s*/i,'').replace(/\s*```\s*$/i,'').trim()),
  () => { const m = rawText.match(/\{[\s\S]*\}/); if (!m) throw new Error('no JSON'); return JSON.parse(m[0]); }
];
for (let i = 0; i < tries.length; i++) {
  try { titlesData = tries[i](); break; } catch(e) { console.log('intento ' + (i+1) + ' fallo: ' + e.message); }
}
if (!titlesData) throw new Error('No se pudo parsear JSON. Raw: ' + rawText.substring(0, 300));

const titles = titlesData.titles || titlesData.results || titlesData.data || [];
console.log('Titulos parseados: ' + titles.length);
if (titles.length === 0) throw new Error('JSON sin titulos. Keys: ' + Object.keys(titlesData).join(', '));

const existingSet = new Set((prev.existingTitles || []).map(t => t.toLowerCase().trim()));
const dateStr = prev.dateStr || new Date().toISOString().slice(0,10).replace(/-/g,'');
const blogId  = String(prev.blogId || 'BLOG');

const rows = [];
let skipped = 0;
for (const t of titles) {
  if (!t.title || String(t.title).trim().length < 5) continue;
  const low = String(t.title).toLowerCase().trim();
  if (existingSet.has(low)) { skipped++; continue; }
  const uid = 'TF' + dateStr + '-' + blogId.substring(0,6).replace(/[^a-z0-9]/gi,'') + '-' + Date.now().toString(36).slice(-4) + '-' + Math.random().toString(36).slice(2,5);
  rows.push({ ID_UNICO: uid, STATUS: 'PENDING', LOCK: 'FALSE', ID_BLOG: blogId, KEYWORD: String(t.keywords || t.title.split(' ').slice(0,4).join(' ')), TEMA_ARTICULO: String(t.title), ID_PARENT_SILO: '', PRIORITY: String(t.priority || 2), RETRY_COUNT: '0' });
}

console.log('Nuevos a insertar: ' + rows.length + ' | Duplicados omitidos: ' + skipped);
if (rows.length === 0) { console.log('WARN: 0 titulos nuevos'); return []; }

return rows.map(r => ({ json: r }));

const allItems = $input.all().map(i => i.json);
const toArchive = allItems.filter(r => { const s = String(r.STATUS??'').toUpperCase().trim(); const retry = parseInt(String(r.RETRY_COUNT||'0'),10); return (s==='FAILED'||s==='LOCK_TIMEOUT') && retry>2 && r.ID_UNICO; });
if (toArchive.length === 0) { console.log('Sin huerfonos.'); return []; }
console.log('Archivando: ' + toArchive.length);
return toArchive.map(r => ({ json: { ID_UNICO: r.ID_UNICO, STATUS: 'ARCHIVED' } }));
